import { workPeriod } from './work-period.js';
import React, { useEffect, useState, useRef, useId } from 'react';
import { createRoot } from 'react-dom/client';
import './style.css';
const months=['Janvier','Fevrier','Mars','Avril','Mai','Juin','Juillet','Aout','Septembre','Octobre','Novembre','Decembre'];
const now=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lagos',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'XAF',maximumFractionDigits:2}).format(Number(n||0));
const date=s=>s?new Date(s).toLocaleDateString('fr-FR'):'';
const statuses={0:'Avaliste',1:'En validation',2:'Fermé',3:'Commissaire',4:'Chef du personnel',5:'Président',6:'Ouvert'};
async function api(path,{body,...options}={}){
 const res=await fetch('/api'+path,{credentials:'same-origin',...options,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body instanceof FormData?body:body===undefined?undefined:JSON.stringify(body)});
 const data=await res.json().catch(()=>({message:'Réponse du serveur illisible.'}));if(!res.ok){const e=new Error(data.message||'Opération impossible.');e.status=res.status;throw e;}return data;
}
function exportCsv(rows,columns,title){const q=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+\-@]/,"'$&")+'"';const csv='\uFEFF'+[columns.map(c=>q(c[1])).join(';'),...rows.map(r=>columns.map(([k])=>q(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])).join(';'))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=title+'.csv';a.click();URL.revokeObjectURL(url);}
const modules={
 arrears:{title:'Échéances en retard',subtitle:'Les versements restant dus',id:'IDECH',columns:[['code','Prêt'],['matricule_sal','Matricule'],['Nom','Nom'],['Prenom','Prénom'],['num_versement','N°'],['date_echeance','Échéance',date],['montant_remb','Prévu',money],['total_amorti','Déjà versé',money],['remaining','Reste à verser',money],['days_late','Jours de retard']]},
 employees:{title:'Salariés',subtitle:'Les membres de votre association',id:'IDEMP',columns:[['Matricule','Matricule'],['Nom','Nom'],['Prenom','Prénom'],['Region','Région'],['SITE','Site'],['MontantCot','Cotisation',money]],fields:[['Matricule','Matricule'],['Civilite','Civilité'],['Nom','Nom'],['Prenom','Prénom'],['MontantCot','Cotisation mensuelle','number'],['SoldeExo','Report initial','number'],['IDREG','Région','regions'],['SITE','Site'],['nouveau','Nouvelle adhésion (droit de 6 500 XAF)','checkbox'],['mois','Mois de début','months']]},
 contributions:{title:'Cotisations',subtitle:'Suivre les versements et les soldes',id:'id',columns:[['Matricule','Matricule'],['Salarie','Salarié'],['report','Report',money],['montant','Cotisation prévue',money],['SoldeAnnuel','Solde',money],['statut','État',v=>v===1?'Actif':'Arrêté']],fields:[['mois','Mois du versement','months'],['montant','Total versé pour ce mois','number'],['Dimunition','Réduction totale du solde','number'],['reason','Motif de la modification']]},
 loans:{title:'Prêts',subtitle:'De la demande au remboursement',id:'IDP',columns:[['matricule_sal','Matricule'],['Nom','Nom'],['Prenom','Prénom'],['montant','Montant',money],['montant_ttc','Montant TTC',money],['montant_apport','Apport',money],['taux','Taux (%)'],['avaliste','Avaliste'],['duree','Versements'],['montant_per','Versement',money],['statut','Étape',(v,r)=>r.refusal_reason?'Refusé':statuses[v]||'À vérifier'],['datepecheance','Première échéance',date]],fields:[['matricule_sal','Salarié','employees'],['montant','Montant du prêt','number'],['duree','Nombre de versements','number'],['taux','Intérêt forfaitaire (%)','number'],['montant_apport','Apport','number'],['periodicite','Intervalle des versements','period'],['avaliste','Avaliste','employees'],['datepecheance','Première échéance','date']]},
 regions:{title:'Régions',subtitle:'Organiser les membres par région',id:'idregion',columns:[['code','Code'],['intitule','Intitulé']],fields:[['code','Code'],['intitule','Intitulé']]},
 entities:{title:'Entités',subtitle:'Les structures de votre association',id:'id_entite',columns:[['libelle','Libellé'],['created_at','Création',date]],fields:[['libelle','Libellé']]},
 charges:{title:'Charges',subtitle:'Suivre les dépenses',id:'id_charge',columns:[['type_charge','Type'],['designation','Désignation'],['montant','Montant',money],['created_at','Création',date]],fields:[['type_charge','Type de charge','chargeType'],['designation','Désignation'],['montant','Montant','number']]},
 placements:{title:'Placements',subtitle:'Suivre les fonds placés',id:'id_placement',columns:[['code','Code'],['intitule','Intitulé'],['montant','Montant',money],['pourcentage','Taux (%)'],['montant_ttc','Montant TTC',money]],fields:[['code','Code (automatique si vide)'],['intitule','Intitulé'],['montant','Montant','number'],['pourcentage','Taux (%)','number']]},
 users:{title:'Utilisateurs',subtitle:'Comptes, rôles et accès',id:'UID',columns:[['username','Identifiant'],['first_name','Prénom'],['Matricule','Matricule'],['roles','Rôles',r=>r.map(x=>x.name).join(', ')],['status','État',v=>v===1?'Actif':'Désactivé']],fields:[['username','Identifiant'],['first_name','Prénom'],['last_name','Nom'],['email','E-mail','email'],['Matricule','Matricule salarié (facultatif)'],['password','Mot de passe (6 caractères minimum)','password'],['RID','Rôle','roles']]},
 repayments:{title:'Remboursements',subtitle:'Historique des versements et reçus',id:'id',columns:[['id','Reçu'],['loan_code','Prêt'],['matricule_sal','Matricule'],['amount','Montant',money],['recorded_at','Enregistré le',v=>new Date(v).toLocaleString('fr-FR')],['reversed_at','État',v=>v?'Annulé':'Enregistré']]},
 audit:{title:'Journal d’activité',subtitle:'Les 200 dernières opérations',id:'id',columns:[['created_at','Date',v=>new Date(v).toLocaleString('fr-FR')],['username','Utilisateur'],['action','Action'],['entity','Module'],['entity_id','Référence']]}
};
const nav=[['dashboard','Vue d’ensemble','◈'],['employees','Salariés','♧'],['contributions','Cotisations','▤'],['loans','Prêts & échéances','↗'],['repayments','Remboursements','⇄'],['arrears','Échéances en retard','◷'],['charges','Charges','−'],['placements','Placements','◇'],['closures','Clôtures mensuelles','▦'],['reports','Bilan annuel','▥'],['regions','Régions','◎'],['entities','Entités','▣'],['users','Utilisateurs','♙'],['audit','Journal d’activité','≡']];
const navGroupLabels={1:'Membres & cotisations',2:'Prêts & remboursements',3:'Finances & clôtures',4:'Administration'};
const navGroup={dashboard:0,employees:1,contributions:1,loans:2,repayments:2,arrears:2,charges:3,placements:3,closures:3,reports:3,regions:4,entities:4,users:4,audit:4};
const userCan=(user,module,action='read')=>!!user&&(user.isAdmin||user.permissions?.[module]?.[action]===true);
function LoadingScreen({message,inline=false}){
 return <main className={'loading-screen'+(inline?' loading-inline':'')} aria-live="polite"><img src="/apes-logo.svg" alt="Logo APES"/><span>{message}</span></main>;
}
const availableClosureMonths=(records,year)=>months.map((_,i)=>i+1).filter(month=>year*100+month<Number(now.slice(0,4))*100+Number(now.slice(5,7))&&!records.some(r=>r.statut===2&&Number(r.annee)*100+Number(r.mois)>=year*100+month));
const currentWorkPeriod=workPeriod(now);
function App(){
 const [headerScrolled,setHeaderScrolled]=useState(()=>window.scrollY>8);
 useEffect(()=>{const update=()=>setHeaderScrolled(window.scrollY>8);window.addEventListener('scroll',update,{passive:true});update();return()=>window.removeEventListener('scroll',update);},[]);

 const [closureTab,setClosureTab]=useState('contributions');
 const contributionClosure=useRef(undefined);
 const [contributionYear,setContributionYear]=useState(currentWorkPeriod.year),[contributionMonth,setContributionMonth]=useState(currentWorkPeriod.month);
 const [theme,setTheme]=useState(()=>{try{const saved=localStorage.getItem('apes-theme');if(saved==='dark'||saved==='light')return saved;}catch{}return window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';});
 const toggleTheme=()=>setTheme(t=>t==='dark'?'light':'dark');
 const [user,setUser]=useState(null),[initial,setInitial]=useState(true),[page,setPage]=useState('dashboard'),[data,setData]=useState(null),[loading,setLoading]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[search,setSearch]=useState(''),[year,setYear]=useState(Number(now.slice(0,4))),[revision,setRevision]=useState(0),[dialog,setDialog]=useState(null),[busy,setBusy]=useState(false),[regions,setRegions]=useState([]),[roles,setRoles]=useState([]),[directory,setDirectory]=useState([]),[mobile,setMobile]=useState(false),[importMode,setImportMode]=useState('create'),[monthlyView,setMonthlyView]=useState(false),[usersTab,setUsersTab]=useState('accounts');
 useEffect(()=>{const activeTheme=user?theme:'light';document.documentElement.dataset.theme=activeTheme;document.documentElement.style.colorScheme=activeTheme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',activeTheme==='dark'?'#10251f':'#087f67');try{localStorage.setItem('apes-theme',theme);}catch{}},[theme,user]);
 const restoreView=u=>{try{const saved=JSON.parse(sessionStorage.getItem('apes-view-'+u.UID)||'null');if(!saved)return;contributionClosure.current=saved.contributionClosure;const allowed=nav.some(([p])=>p===saved.page)&&(saved.page==='dashboard'||userCan(u,saved.page));if(allowed)setPage(saved.page);if(Number.isInteger(saved.year)&&saved.year>=2000&&saved.year<=2100){if(saved.page==='contributions')setContributionYear(saved.year);else setYear(saved.year);}if(Number.isInteger(saved.contributionMonth)&&saved.contributionMonth>=1&&saved.contributionMonth<=12)setContributionMonth(saved.contributionMonth);}catch{}};
 useEffect(()=>{if(!user)return;try{sessionStorage.setItem('apes-view-'+user.UID,JSON.stringify({page,year:page==='contributions'?contributionYear:year,contributionMonth,contributionClosure:contributionClosure.current}));}catch{}},[user,page,year,contributionYear,contributionMonth]);
 useEffect(()=>{api('/auth/me').then(u=>{restoreView(u);setUser(u);}).catch(e=>{if(e.status!==401)setError(e.message);}).finally(()=>setInitial(false));},[]);
 useEffect(()=>{if(!user)return;let alive=true;setLoading(true);setError('');setData(null);api('/'+page+(['contributions','reports'].includes(page)?`?year=${page==='contributions'?contributionYear:year}`:'')).then(d=>{if(alive)setData(d);}).catch(e=>{if(alive){setError(e.message);if(e.status===401)setUser(null);}}).finally(()=>{if(alive)setLoading(false);});return()=>{alive=false;};},[user,page,year,contributionYear,revision]);
 useEffect(()=>{if(!user)return;api('/regions').then(setRegions).catch(()=>{});api('/directory').then(setDirectory).catch(()=>{});if(userCan(user,'users'))api('/roles').then(setRoles).catch(()=>{});},[user,revision]);
 useEffect(()=>{if(!user||user.must_change_password||page!=='contributions')return;let alive=true;api('/contributions/period').then(period=>{if(!alive)return;if(contributionClosure.current!==period.closureKey){contributionClosure.current=period.closureKey;setContributionYear(period.year);setContributionMonth(period.month);}}).catch(e=>{if(alive)setError(e.message);});return()=>{alive=false;};},[user,page,revision]);
 const refresh=()=>setRevision(n=>n+1);
 const download=async(path,name)=>{setBusy(true);try{const res=await fetch('/api'+path);if(!res.ok){const d=await res.json();throw new Error(d.message);}const url=URL.createObjectURL(await res.blob());const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}catch(e){setError(e.message);}finally{setBusy(false);}};
 const mutate=async(path,body,method='POST')=>{setBusy(true);setError('');try{const result=await api(path,{method,body});setNotice(path==='/employees'&&result.account?.created?'Salarié et compte créés. Identifiant : '+result.account.username+' · Mot de passe initial : 123456 (changement obligatoire).':'Opération enregistrée.');refresh();return true;}catch(e){setError(e.message);return false;}finally{setBusy(false);}};
 async function login(e){e.preventDefault();setBusy(true);setError('');try{await api('/auth/login',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});const u=await api('/auth/me');setPage('dashboard');setData(null);setSearch('');setNotice('');setMobile(false);setUser(u);}catch(e){setError(e.message);}finally{setBusy(false);}}
 useEffect(()=>{if(dialog?.path!=='/closures'||!dialog.values||!data)return;const allowed=availableClosureMonths(data[dialog.values.type]||[],Number(dialog.values.annee));if(!allowed.includes(Number(dialog.values.mois)))setDialog(d=>d?.path==='/closures'?{...d,values:{...d.values,mois:allowed[0]||''}}:d);},[dialog?.path,dialog?.values?.type,dialog?.values?.annee,data]);
 if(initial)return <LoadingScreen message="Chargement APES..."/>;
 if(!user)return <Login onLogin={login} busy={busy} error={error}/>;
 if(user.must_change_password)return <RequiredPasswordChange user={user} onComplete={async(current,password)=>{await api('/auth/password',{method:'POST',body:{current,password}});await api('/auth/login',{method:'POST',body:{username:user.username,password}});setPage('dashboard');setData(null);setUser(await api('/auth/me'));refresh();}} onLogout={async()=>{await api('/auth/logout',{method:'POST',body:{}});setUser(null);}}/>;
 const meta=modules[page],filtered=Array.isArray(data)?data.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())):[];
 const changePage=p=>{setMobile(false);if(p===page)return;setData(null);setPage(p);setSearch('');setNotice('');setError('');};
 const visibleColumns=page==='contributions'&&monthlyView?[['Matricule','Matricule'],['Salarie','Salarié'],['report','Report',money],...months.map(m=>[m,m,money]),['DroitAdhesion','Adhésion',money],['Dimunition','Réduction',money],['SoldeArret','Solde d’arrêt',money],['closedTotal','Cotisations calculées · mois clôturés',money],['SoldeAnnuel','Solde',money]]:page==='contributions'?[['Matricule','Matricule'],['Salarie','Salarié'],['montant','Cotisation prévue',money],[months[contributionMonth-1],'Versé · '+months[contributionMonth-1],money],['closedTotal','Cotisations calculées · mois clôturés',money],['SoldeAnnuel','Solde annuel',money],['statut','État',v=>v===1?'Actif':'Arrêté']]:meta?.columns;
 const openCreate=()=>{const values=Object.fromEntries(meta.fields.map(([k,,t])=>[k,t==='number'?0:t==='checkbox'?false:t==='months'?Number(now.slice(5,7)):t==='date'?now:t==='period'?'1':'']));if(page==='employees')values.MontantCot=3000;if(page==='charges')values.type_charge='Sortie';if(page==='loans'){values.duree=6;values.taux=5;values.matricule_sal=user.Matricule||'';}setDialog({title:'Nouveau : '+meta.title,fields:meta.fields,values,path:'/'+page,method:'POST'});};
 const editRow=row=>{let fields=meta.fields,values={...row},method='PUT';if(page==='charges')values.montant=Math.abs(Number(row.montant));if(page==='employees')fields=fields.filter(([k])=>!['nouveau','mois'].includes(k));if(page==='contributions'){values.reason='';values.mois=contributionMonth;values.montant=row[months[values.mois-1]];}if(page==='users'){fields=[['RID','Rôle','roles'],['status','État du compte','status']];values.RID=row.roles[0]?.RID||'';method='PATCH';}setDialog({title:'Modifier : '+meta.title,fields,values,path:`/${page}/${row[meta.id]}`,method,row});};
 const showPayments=async row=>{setBusy(true);try{setDialog({title:'Échéancier · '+row.code,payments:await api(`/loans/${row.IDP}/payments`),loan:row});}catch(e){setError(e.message);}finally{setBusy(false);}};
 const canSign=(row,action='sign')=>!userCan(user,'loans',action)?false:user.isAdmin?[0,3,4,5].includes(row.statut):row.statut===0?!!user.Matricule&&row.avaliste===user.Matricule:user.roles.includes({3:'commissaire',4:'chef_personnel',5:'president'}[row.statut]);
 return <div className="app-shell"><aside className={'sidebar '+(mobile?'open':'')}><div className="brand"><img className="brand-logo" src="/apes-logo.svg" alt="" width="48" height="48"/><div>APES<small>GESTION ASSOCIATIVE</small></div></div><p className="nav-caption">ESPACE DE TRAVAIL</p><nav>{nav.filter(([p])=>p==='dashboard'||userCan(user,p)).flatMap(([p,t,icon],i,items)=>[...(i>0&&navGroup[p]!==navGroup[items[i-1][0]]?[<div key={'separator-'+p} className="nav-section-label"><span>{navGroupLabels[navGroup[p]]}</span></div>]:[]),<button key={p} className={page===p?'active':''} onClick={()=>changePage(p)}><span>{icon}</span>{t}</button>])}</nav><div className="sidebar-bottom"><span className="status-dot"/> © {new Intl.DateTimeFormat('en', {timeZone:'Africa/Lagos',year:'numeric'}).format(new Date())} Sorepco · Gestion Associative</div></aside><div className="workspace"><header className={'topbar'+(headerScrolled?' is-scrolled':'')}><button className="mobile-menu" onClick={()=>setMobile(!mobile)} aria-label="Ouvrir le menu">☰</button><span>Association / <b>{meta?.title||(page==='dashboard'?'Vue d’ensemble':page==='reports'?'Bilan annuel':'Clôtures mensuelles')}</b></span><div className="header-account"><ThemeToggle theme={theme} onToggle={toggleTheme}/><ProfileMenu user={user} onAccount={()=>setDialog({title:'Changer mon mot de passe',fields:[['current','Mot de passe actuel','password'],['password','Nouveau mot de passe (6 caractères minimum)','password']],values:{current:'',password:''},path:'/auth/password',method:'POST'})} onLogout={()=>setDialog({title:'Confirmer la déconnexion',logout:true})}/></div></header><main className="content"><div className="page-heading"><div><p className="overline">{meta?.subtitle||'Votre association au quotidien'}</p><h1>{meta?.title||(page==='dashboard'?'Vue d’ensemble':page==='reports'?'Bilan annuel':'Clôtures mensuelles')}</h1></div><span className="today">{new Date(now).toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'})}</span></div>{error&&<div className="alert error" role="alert">{error}<button onClick={()=>setError('')} aria-label="Fermer">×</button></div>}{notice&&<div className="alert success" role="status">{notice}<button onClick={()=>setNotice('')} aria-label="Fermer">×</button></div>}{page==='users'&&user.isAdmin&&<div className="users-tabs" role="tablist" aria-label="Gestion des utilisateurs"><button role="tab" aria-selected={usersTab==='accounts'} className={usersTab==='accounts'?'active':''} onClick={()=>setUsersTab('accounts')}>Utilisateurs</button><button role="tab" aria-selected={usersTab==='permissions'} className={usersTab==='permissions'?'active':''} onClick={()=>setUsersTab('permissions')}>Droits d’accès</button></div>}{loading?<LoadingScreen message="Chargement..." inline/>:!data?<div className="empty"><h3>Données indisponibles</h3><p>Vérifiez la connexion SQL Server et réessayez.</p><button onClick={refresh}>Réessayer</button></div>:page==='dashboard'?<Dashboard data={data} user={user} changePage={changePage} refresh={refresh}/>:page==='reports'?<FinancialReport data={data} year={year} setYear={setYear} refresh={refresh} download={download} busy={busy} canExport={userCan(user,'reports','export')}/>:page==='closures'?<><div className="users-tabs" role="tablist" aria-label="Modules de clôture">{[['contributions','Cotisations'],['loans','Prêts']].map(([key,label])=><button key={key} id={'closure-tab-'+key} role="tab" aria-selected={closureTab===key} aria-controls={'closure-panel-'+key} className={closureTab===key?'active':''} onClick={()=>setClosureTab(key)}>{label}</button>)}</div><section className="card"><div className="section-heading"><div><h2>Clôturer un mois · {closureTab==='contributions'?'Cotisations':'Prêts'}</h2><p className="muted">La clôture bloque les modifications du mois choisi et de tous les mois précédents, y compris les années précédentes.</p></div><button disabled={!userCan(user,'closures','close')} className="primary" onClick={()=>setDialog({title:'Clôture mensuelle',fields:[['annee','Année','number'],['mois','Mois','months']],values:{type:closureTab,annee:year,mois:Number(now.slice(5,7))},path:'/closures',method:'POST',confirm:true})}>Clôturer un mois</button></div></section>{[['contributions','Cotisations'],['loans','Prêts']].filter(([key])=>key===closureTab).map(([key,t])=><section className="card" key={key} role="tabpanel" id={'closure-panel-'+key} aria-labelledby={'closure-tab-'+key}><Table title={t} rows={data[key]} id="id" columns={key==='contributions'?[['annee','Année'],['mois','Mois',v=>months[v-1]],['solde','Versements enregistrés du mois',money],['closedTotal','Cotisations calculées cumulées',money],['statut','État',v=>v===2?'Clôturé':'Ouvert']]:[['annee','Année'],['mois','Mois',v=>months[v-1]],['total_prets','Échéances prévues',money],['total_remb','Versements',money],['statut','État',v=>v===2?'Clôturé':'Ouvert']]}/></section>)}</>:page==='users'&&usersTab==='permissions'?<PermissionsPanel/>:<section className="card table-card"><div className="toolbar"><input className="search" aria-label="Rechercher" placeholder="Rechercher dans la liste…" value={search} onChange={e=>setSearch(e.target.value)}/>{page==='contributions'&&<input type="number" aria-label="Année" min="2000" max="2100" value={contributionYear} onChange={e=>setContributionYear(Number(e.target.value))}/>}{page==='contributions'&&<label className="work-month-filter">Mois travaillé<select value={contributionMonth} onChange={e=>setContributionMonth(Number(e.target.value))}>{months.map((m,i)=><option key={m} value={i+1}>{m}</option>)}</select></label>}{page==='contributions'&&<button aria-pressed={monthlyView} onClick={()=>setMonthlyView(v=>!v)}>{monthlyView?'Vue du mois':'Vue annuelle'}</button>}{page==='contributions'&&userCan(user,'contributions','generate')&&<button disabled={busy} onClick={()=>setDialog({title:'Déclarer les cotisations du mois',monthlyBatch:true,year:contributionYear,month:contributionMonth})}>Générer le mois</button>}{page==='contributions'&&userCan(user,'contributions','open_year')&&<button disabled={busy} onClick={()=>setDialog({title:'Ouvrir une année de cotisation',openYear:contributionYear})}>Ouvrir cette année</button>}<IconButton icon="refresh" label="Actualiser" disabled={busy} onClick={refresh}/><span className="count">{filtered.length} résultat(s)</span>{userCan(user,page,'export')&&<button onClick={()=>exportCsv(filtered,visibleColumns,meta.title)}>CSV</button>}{page!=="users"&&userCan(user,page,'export')&&<button disabled={busy} onClick={()=>download(`${page==='arrears'?'/arrears/export':'/exports/'+page}${page==='contributions'?'?year='+contributionYear:''}`,`apes-${page}.xlsx`)}>Excel</button>}<IconButton icon="print" label="Imprimer" onClick={()=>window.print()}/>{page==='employees'&&userCan(user,'employees','import')&&<><button disabled={busy} onClick={()=>download('/employees/template','apes-import-salaries.xlsx')}>Modèle XLSX</button><button disabled={busy} onClick={()=>download('/employees/template.csv','apes-import-salaries.csv')}>Modèle CSV</button><select className="import-mode" aria-label="Mode d’import des salariés" value={importMode} onChange={e=>setImportMode(e.target.value)}><option value="create">Créer uniquement</option><option value="update">Créer / mettre à jour les profils</option></select><label className="button import-button">Importer CSV / XLSX / XLS<input type="file" accept=".xlsx,.xls,.csv" hidden onChange={async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;setBusy(true);setError('');try{const body=new FormData();body.append('file',f);body.append('mode',importMode);const preview=await api('/employees/import/preview',{method:'POST',body});setDialog({title:'Vérifier l’import · '+f.name,importPreview:preview,file:f,importMode});}catch(e){setError(e.message);}finally{setBusy(false);}}}/></label></>}{meta?.fields&&page!=='contributions'&&userCan(user,page,'create')&&<button className="primary" onClick={openCreate}>+ Nouveau</button>}</div>{page==='contributions'&&<p className="table-note">Mois travaillé : <strong>{months[contributionMonth-1]} {contributionYear}</strong>. Les cotisations du salaire payé le mois suivant sont enregistrées sur ce mois travaillé.</p>}{page==='arrears'&&<><div className="stats two"><article className="stat"><span>Reste à verser · résultats affichés</span><strong>{money(filtered.reduce((s,r)=>s+Number(r.remaining),0))}</strong></article><article className="stat"><span>Échéances en retard</span><strong>{filtered.length}</strong></article></div><p className="table-note">Situation au {date(now)} : échéances antérieures à aujourd’hui, sur prêts ouverts, avec un montant restant. Les versements partiels et les anciens cumuls sont pris en compte. Aucune pénalité automatique.</p></>}{page==='repayments'&&<p className="table-note">Ce journal contient les versements enregistrés dans la nouvelle application. Les anciens cumuls restent consultables dans les échéances.</p>}{page==='employees'&&user.isAdmin&&<p className="table-note">Formats acceptés : CSV, XLSX et XLS. Le fichier doit contenir les colonnes suivantes, dans cet ordre : Matricule, Civilite, Nom, Prenom, MontantCot, SoldeExo, Region, IDREG et SITE. Les régions doivent être créées dans l’application avant l’import.</p>}<Table rows={filtered} columns={visibleColumns} id={meta.id} title={meta.title} actions={row=><>{page==='employees'&&<IconButton icon="folder" label="Dossier membre" className="small" disabled={busy} onClick={async()=>{setBusy(true);try{const statement=await api('/employees/'+row.IDEMP+'/statement');setDialog({title:'Dossier membre · '+row.Matricule,statement});}catch(e){setError(e.message);}finally{setBusy(false);}}}/>}{userCan(user,page,'update')&&['employees','contributions','entities','charges','placements','users','regions'].includes(page)&&<IconButton icon="edit" label="Modifier" className="small" onClick={()=>editRow(row)}/>}{userCan(user,page,'delete')&&['entities','charges','placements'].includes(page)&&<IconButton icon="trash" label="Supprimer" className="small danger" disabled={busy} onClick={()=>{if(window.confirm('Supprimer cet enregistrement ?'))mutate(`/${page}/${row[meta.id]}`,undefined,'DELETE');}}/>} {page==='contributions'&&userCan(user,'contributions','stop')&&row.statut===1&&<IconButton icon="stop" label="Arrêter les cotisations" className="small danger" disabled={busy} onClick={()=>{if(window.confirm('Arrêter les cotisations de ce membre ?'))mutate(`/contributions/${row.id}/stop`,{});}}/>}{page==='contributions'&&<IconButton icon="eye" label="Détails des versements" className="small" disabled={busy} onClick={async()=>{setBusy(true);try{setDialog({title:'Versements · '+row.Salarie,details:row,history:await api('/contributions/'+row.id+'/history'),contributionSummary:await api('/contributions/'+row.id+'/summary')});}catch(e){setError(e.message);}finally{setBusy(false);}}}/>}{['loans','arrears'].includes(page)&&<IconButton icon="calendar" label="Voir les échéances" className="small" disabled={busy} onClick={()=>showPayments(row)}/>}{page==='loans'&&<> {userCan(user,'loans','payoff')&&row.statut===6&&<IconButton icon="cash" label="Solder le prêt" className="small" disabled={busy} onClick={async()=>{setBusy(true);try{const payments=await api('/loans/'+row.IDP+'/payments'),expected=Math.round(payments.reduce((s,p)=>s+Math.max(0,Number(p.montant_remb)-Number(p.total_amorti||0)),0)*100)/100;setDialog({title:'Remboursement anticipé · '+row.code,fields:[['reason','Motif / référence du règlement']],values:{reason:'',expected,request_key:crypto.randomUUID()},path:'/loans/'+row.IDP+'/payoff',method:'POST',confirm:true,payoffAmount:expected});}catch(e){setError(e.message);}finally{setBusy(false);}}}/>}{canSign(row)&&<IconButton icon="check" label="Signer l’étape" className="small primary" disabled={busy} onClick={()=>{if(window.confirm(`Signer l’étape « ${statuses[row.statut]} » ?`))mutate(`/loans/${row.IDP}/sign`,{});}}/>}{canSign(row,'reject')&&<IconButton icon="close" label="Refuser le prêt" className="small danger" disabled={busy} onClick={()=>setDialog({title:'Refuser · '+row.code,fields:[['reason','Motif du refus']],values:{reason:''},path:`/loans/${row.IDP}/reject`,method:'POST'})}/>}</>} {page==='repayments'&&<><IconButton icon="receipt" label="Voir le reçu" className="small" disabled={busy} onClick={async()=>{try{setDialog({title:'Reçu de remboursement',receipt:await api('/repayments/'+row.id+'/receipt')});}catch(e){setError(e.message);}}}/>{userCan(user,'repayments','reverse')&&!row.reversed_at&&<IconButton icon="undo" label="Annuler le versement" className="small danger" disabled={busy} onClick={()=>setDialog({title:'Annuler le versement n° '+row.id,fields:[['reason','Motif obligatoire']],values:{reason:''},path:'/repayments/'+row.id+'/reverse',method:'POST',confirm:true})}/>}</>} {page==='users'&&userCan(user,'users','update')&&<IconButton icon={row.status===1?'lock':'unlock'} label={row.status===1?'Désactiver le compte':'Réactiver le compte'} className="small" disabled={busy||row.UID===user.UID} onClick={()=>{const status=row.status===1?0:1;setDialog({title:status===0?'D\u00e9sactiver le compte':'R\u00e9activer le compte',confirmation:{path:'/users/'+row.UID+'/status',method:'PATCH',body:{status},message:status===0?'Le compte de '+row.username+' sera d\u00e9sactiv\u00e9 et sa session sera ferm\u00e9e.':'Le compte de '+row.username+' pourra \u00e0 nouveau se connecter.',submitLabel:status===0?'D\u00e9sactiver':'R\u00e9activer'}});}}/>}{page==='users'&&user.isAdmin&&<IconButton icon="trash" label="Supprimer le compte" className="small danger" disabled={busy||row.UID===user.UID} onClick={()=>setDialog({title:'Supprimer le compte',confirmation:{path:'/users/'+row.UID,method:'DELETE',danger:true,submitLabel:'Supprimer d\u00e9finitivement',message:'Le compte '+row.username+' sera supprim\u00e9. Cette action est irr\u00e9versible. Un compte li\u00e9 \u00e0 un historique ou au dernier administrateur actif ne peut pas \u00eatre supprim\u00e9.'}})}/>}{page==='users'&&userCan(user,'users','reset_password')&&<IconButton icon="key" label="Réinitialiser le mot de passe" className="small" onClick={()=>setDialog({title:'Réinitialiser · '+row.username,fields:[['password','Nouveau mot de passe (6 caractères minimum)','password']],values:{password:''},path:`/users/${row.UID}/password`,method:'POST'})}/>}</>}/></section>}<footer>APES · Gestion associative</footer></main></div>{dialog&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget&&!busy)setDialog(null);}}><section className={'modal '+(dialog.importPreview||dialog.statement||dialog.monthlyBatch?'import-modal':'')} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><h2 id="dialog-title">{dialog.title}</h2><button aria-label="Fermer" disabled={busy} onClick={()=>setDialog(null)}>×</button></header>{error&&<div className="alert error" role="alert">{error}</div>}{dialog.monthlyBatch?<MonthlyBatch initialMonth={dialog.month} year={dialog.year} busy={busy} onCancel={()=>setDialog(null)} onConfirm={async values=>{if(await mutate('/contributions/month/apply',values))setDialog(null);}}/>:dialog.closureReview?<ClosureReview values={dialog.values} busy={busy} onBack={()=>setDialog(d=>({...d,closureReview:false,fields:d.returnFields,title:'Clôture mensuelle'}))} onConfirm={async()=>{if(await mutate(dialog.path,dialog.values,dialog.method))setDialog(null);}}/> :dialog.openYear?<YearOpening year={dialog.openYear} busy={busy} onCancel={()=>setDialog(null)} onConfirm={async()=>{if(await mutate('/contributions/year',{year:dialog.openYear}))setDialog(null);}}/>:dialog.confirmation?<><p>{dialog.confirmation.message}</p><div className="modal-actions"><button disabled={busy} onClick={()=>setDialog(null)}>Annuler</button><button className={dialog.confirmation.danger?'danger':'primary'} disabled={busy} onClick={async()=>{if(await mutate(dialog.confirmation.path,dialog.confirmation.body,dialog.confirmation.method))setDialog(null);}}>{busy?'Traitement...':dialog.confirmation.submitLabel}</button></div></>:dialog.logout?<><p>Voulez-vous vous déconnecter de votre compte APES ?</p><div className="modal-actions"><button disabled={busy} onClick={()=>setDialog(null)}>Annuler</button><button className="primary" disabled={busy} onClick={async()=>{setBusy(true);setError('');try{await api('/auth/logout',{method:'POST'});setDialog(null);setUser(null);setData(null);setPage('dashboard');setNotice('');}catch(e){setError(e.message);}finally{setBusy(false);}}}>{busy?'Déconnexion…':'Se déconnecter'}</button></div></>:dialog.statement?<MemberStatement data={dialog.statement}/>:dialog.importPreview?<ImportReview preview={dialog.importPreview} busy={busy} onCancel={()=>setDialog(null)} onImport={async()=>{const body=new FormData();body.append('file',dialog.file);body.append('mode',dialog.importMode||'create');if(await mutate('/employees/import',body)){setNotice(dialog.importPreview.total+' ligne(s) traitée(s).');setDialog(null);}}}/>:dialog.fields?<form onSubmit={async e=>{e.preventDefault();if(dialog.path==='/closures'){setDialog(d=>({...d,closureReview:true,returnFields:d.fields,fields:undefined,title:'Confirmer la clôture'}));return;}if(dialog.confirm&&!window.confirm('Confirmer cette opération ?'))return;if(await mutate(dialog.path,dialog.values,dialog.method))setDialog(null);}}>{dialog.payoffAmount!==undefined&&<div className="report-notice">Montant à enregistrer : <strong>{money(dialog.payoffAmount)}</strong>. Confirmez uniquement après réception du règlement. Chaque échéance sera soldée avec un reçu ; aucune pénalité n’est ajoutée.</div>}<div className="form-grid">{dialog.fields.map(([k,label,t])=><Field key={k==='avaliste'?k+':'+dialog.values.matricule_sal:k} field={[k,label,t]} allowedMonths={dialog.path==='/closures'&&k==='mois'?availableClosureMonths(data?.[dialog.values.type]||[],Number(dialog.values.annee)):undefined} value={dialog.values[k]} regions={regions} roles={roles} directory={k==='avaliste'?directory.filter(e=>e.Matricule!==dialog.values.matricule_sal):directory} optional={page==='placements'&&k==='code'||['Civilite','Prenom','SITE','last_name','email'].includes(k)||page==='users'&&k==='Matricule'} disabled={page==='employees'&&dialog.method==='PUT'&&k==='Matricule'||page==='loans'&&k==='matricule_sal'&&!userCan(user,'loans','read_all')} onChange={v=>setDialog(d=>{const values={...d.values,[k]:v};if(page==='contributions'&&k==='mois')values.montant=d.row[months[v-1]];if(page==='loans'&&k==='matricule_sal'&&values.avaliste===v)values.avaliste='';return {...d,values};})}/>)}</div>{page==='loans'&&dialog.path==='/loans'&&<LoanPreview values={dialog.values}/>} {page==='loans'&&<p className="table-note">Intérêt forfaitaire sur le montant initial. La durée correspond au nombre de versements. Les échéances tombent en fin de mois, comme dans APES actuel.</p>}{dialog.path?.includes('password')&&<p className="table-note">Après ce changement, utilisez la nouvelle application pour vous connecter. Le mot de passe ne fonctionnera plus dans l’ancienne application PHP.</p>}<div className="modal-actions"><button type="button" disabled={busy} onClick={()=>setDialog(null)}>Annuler</button><button className="primary" disabled={busy||(dialog.path==='/closures'&&!dialog.values.mois)}>{busy?'Enregistrement…':'Enregistrer'}</button></div></form>:dialog.receipt?<Receipt row={dialog.receipt}/>:dialog.details?<><p className="table-note">Cotisation mensuelle de {money(dialog.details.montant)}, de janvier jusqu’au dernier mois clôturé de {dialog.details.annee}.</p><Table rows={dialog.contributionSummary?.rows||[]} columns={[['name','Mois'],['amount','Cotisation mensuelle',money]]} id="id"/><div className="contribution-summary-total"><span>Total des cotisations sur la période</span><strong>{money(dialog.contributionSummary?.total)}</strong></div><p className="table-note">Total calculé : cotisation mensuelle × nombre de mois clôturés. Versements effectivement enregistrés sur cette période : {money(dialog.contributionSummary?.recordedTotal)}.</p><p>Adhésion : {money(dialog.details.DroitAdhesion)} · Réduction : {money(dialog.details.Dimunition)} · Solde d’arrêt : {money(dialog.details.SoldeArret)}</p><h3>Historique des modifications</h3><p className="table-note">Les modifications enregistrées dans la nouvelle application sont affichées ici.</p><Table rows={dialog.history||[]} id="id" columns={[['recorded_at','Date',v=>new Date(v).toLocaleString('fr-FR')],['username','Utilisateur'],['month_number','Mois',v=>v?months[v-1]:'—'],['month_before','Avant',money],['month_after','Après',money],['reduction_before','Réduction avant',money],['reduction_after','Réduction après',money],['balance_after','Solde après',money],['reason','Motif']]}/></>:<><p className="muted">L’échéancier est créé après la signature du président.</p>{dialog.loan.refusal_reason&&<div className="alert error">Motif du refus : {dialog.loan.refusal_reason}</div>}<Table rows={dialog.payments} id="IDECH" columns={[['num_versement','N°'],['date_echeance','Date',date],['montant_remb','Prévu',money],['total_amorti','Versé',money],['statut','État',v=>v===2?'Réglé':'À régler']]} actions={row=>userCan(user,'repayments','pay')&&row.statut!==2&&<button className="small primary" disabled={busy} onClick={()=>setDialog({title:'Enregistrer un remboursement',fields:[['montant','Montant versé','number']],values:{montant:Math.round((Number(row.montant_remb)-Number(row.total_amorti))*100)/100,request_key:crypto.randomUUID()},path:`/payments/${row.IDECH}/pay`,method:'POST'})}>Verser</button>}/></>}</section></div>}</div>;
}
function ImportReview({preview,busy,onCancel,onImport}){
 const entries=preview.entries.map(e=>({line:e.line,...e.values,effectiveRegion:e.effectiveRegion,operation:e.operation,issues:e.issues,warnings:e.warnings}));
 const messages=list=>list.length?<ul className="import-messages">{list.map((message,i)=><li key={i}>{message}</li>)}</ul>:<span className="muted">—</span>;
 return <><div className="import-summary"><span>{preview.total} ligne(s)</span><span className="success-text">{preview.valid} valide(s)</span><span className={preview.invalid?'error-text':''}>{preview.invalid} en erreur</span></div><p className="table-note">Vérification uniquement : aucune donnée n’a encore été enregistrée. L’import conserve les reports indiqués et crée un compte membre pour chaque salarié sans compte, avec le mot de passe initial 123456 à changer obligatoirement à la première connexion. Corrigez le fichier puis sélectionnez-le à nouveau si une ligne est invalide.</p><Table rows={entries} id="line" columns={[['line','Ligne'],['operation','Action'],['Matricule','Matricule'],['Nom','Nom'],['Prenom','Prénom'],['effectiveRegion','Région'],['MontantCot','Cotisation',v=>v==null?'—':money(v)],['SoldeExo','Report',v=>v==null?'—':money(v)],['issues','Erreurs',messages],['warnings','Remarques',messages]]}/><div className="modal-actions"><button disabled={busy} onClick={onCancel}>Fermer</button><button className="primary" disabled={busy||!preview.canImport} onClick={onImport}>{busy?'Import en cours…':'Confirmer le traitement de '+preview.total+' ligne(s)'}</button></div></>;
}
function FinancialReport({data,year,setYear,refresh,download,busy,canExport}){
 const cols=[['month','Mois'],['contributions','Cotisations',money],['closedContributions','Cotisations calculées · mois clôturés',money],['scheduled','Échéances prévues',money],['received','Remboursements datés',money],['charges','Sorties',money],['income','Entrées',money]];
 return <><section className="card"><div className="toolbar"><label className="report-year">Année<select value={year} onChange={e=>setYear(Number(e.target.value))}>{Array.from({length:Number(now.slice(0,4))-1998},(_,i)=>Number(now.slice(0,4))+1-i).map(y=><option key={y} value={y}>{y}</option>)}</select></label><IconButton icon="refresh" label="Actualiser" disabled={busy} onClick={refresh}/><span className="count">Montants en XAF</span><button disabled={busy||!canExport} className="primary" onClick={()=>download('/reports/export?year='+year,'apes-bilan-'+year+'.xlsx')}>Excel</button><button disabled={!canExport} onClick={()=>exportCsv(data.rows,cols,'apes-bilan-'+year)}>CSV</button><IconButton icon="print" label="Imprimer" onClick={()=>window.print()}/></div><p className="table-note">Bilan de gestion : les cotisations déclarées sont les versements enregistrés. Les cotisations calculées reprennent le montant mensuel de janvier jusqu’à la dernière clôture de l’année. Les remboursements correspondent aux nouveaux versements datés, hors annulations. Ce bilan ne représente pas le solde bancaire.</p>{data.legacyUndated>0&&<p className="report-notice">{money(data.legacyUndated)} de remboursements historiques sans date (toutes années) restent dans les échéances et sont exclus de la répartition mensuelle.</p>}</section><div className="stats">{[['Cotisations déclarées','contributions'],['Cotisations calculées · mois clôturés','closedContributions'],['Échéances prévues','scheduled'],['Remboursements datés nets','received'],['Charges enregistrées','charges']].map(([label,key])=><article className="stat" key={key}><span>{label}</span><strong>{money(data.totals[key])}</strong><small>Année {year}</small></article>)}</div><section className="card"><h2>Évolution mensuelle</h2><MonthlyChart rows={data.rows}/></section><section className="card"><div className="section-heading"><h2>Détail par mois</h2><span className="muted">Généré le {new Date(data.generatedAt).toLocaleString('fr-FR')}</span></div><Table rows={data.rows} columns={cols} id="month_number"/></section></>;
}
function MonthlyChart({rows}){
 const series=[['contributions','Cotisations','#0b9e79'],['scheduled','Échéances prévues','#508dde'],['received','Remboursements datés','#e9ae36'],['charges','Sorties','#d77480'],['income','Entrées','#8c76d5']];
 const [visible,setVisible]=useState(['contributions','scheduled','received','charges','income']);
 const active=series.filter(([key])=>visible.includes(key)),max=Math.max(1,...rows.flatMap(row=>active.map(([key])=>row[key]||0)));
 const plot={left:75,top:15,width:865,height:195},group=plot.width/12,bar=Math.min(13,group/(active.length+2));
 return <><div className="chart-legend">{series.map(([key,label,color])=><button key={key} aria-pressed={visible.includes(key)} className={visible.includes(key)?'selected':''} onClick={()=>setVisible(v=>v.includes(key)?v.filter(k=>k!==key):[...v,key])}><span style={{background:color}}/>{label}</button>)}</div><div className="chart-scroll"><svg viewBox="0 0 960 255" role="img" aria-label="Comparaison mensuelle des cotisations, échéances, remboursements et charges. Les valeurs exactes figurent dans le tableau suivant."><title>Bilan mensuel de gestion</title>{[0,.25,.5,.75,1].map(f=><g key={f}><line x1={plot.left} y1={plot.top+plot.height*(1-f)} x2={940} y2={plot.top+plot.height*(1-f)} stroke="#e3e9e2"/><text x={plot.left-10} y={plot.top+plot.height*(1-f)+4} textAnchor="end" fill="#738378" fontSize="10">{new Intl.NumberFormat('fr-FR',{notation:'compact',maximumFractionDigits:1}).format(max*f)}</text></g>)}{rows.map((row,index)=><g key={row.month_number}>{active.map(([key,label,color],j)=>{const height=(row[key]||0)/max*plot.height;return <rect key={key} x={plot.left+index*group+group/2-active.length*bar/2+j*bar} y={plot.top+plot.height-height} width={bar-2} height={height} fill={color} rx="2"><title>{row.month} · {label} : {money(row[key])}</title></rect>;})}<text x={plot.left+index*group+group/2} y={233} textAnchor="middle" fill="#738378" fontSize="11">{row.month.slice(0,3)}</text></g>)}</svg></div>{!visible.length&&<p className="table-note">Sélectionnez un indicateur pour afficher ses montants.</p>}</>;
}
function LoanPreview({values}){
 const [preview,setPreview]=useState(null),[error,setError]=useState('');
 const {montant,taux,montant_apport,duree,periodicite,datepecheance}=values;
 useEffect(()=>{const abort=new AbortController();setPreview(null);setError('');if(!(montant>0)||!(duree>0)||!datepecheance)return;const timer=setTimeout(()=>{api('/loans/preview',{method:'POST',body:{montant,taux,montant_apport,duree,periodicite,datepecheance},signal:abort.signal}).then(setPreview).catch(e=>{if(e.name!=='AbortError')setError(e.message);});},300);return()=>{clearTimeout(timer);abort.abort();};},[montant,taux,montant_apport,duree,periodicite,datepecheance]);
 return <section className="loan-preview" aria-live="polite"><h3>Aperçu du financement</h3>{error?<p className="preview-error">{error}</p>:preview?<div className="preview-grid"><div><small>Montant TTC</small><strong>{money(preview.total)}</strong></div><div><small>Après apport</small><strong>{money(preview.financed)}</strong></div><div><small>Premier versement</small><strong>{money(preview.first)}</strong></div><div><small>Dernier versement</small><strong>{money(preview.last)}</strong></div><div><small>Dernière échéance</small><strong>{date(preview.end)}</strong></div></div>:<p className="table-note">Renseignez le montant et les conditions pour afficher l’échéancier prévisionnel.</p>}{preview&&<details><summary>Voir les échéances prévisionnelles</summary><Table rows={preview.payments} id="num_versement" columns={[['num_versement','N°'],['date_echeance','Date',date],['montant_remb','Versement',money],['solde','Solde après versement',money]]}/></details>}</section>;
}
function Receipt({row}){
 const reference='APES-R'+String(row.id).padStart(6,'0');
 const print=()=>{const popup=window.open('','_blank','width=800,height=700');if(!popup)return;popup.document.write('<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Reçu APES</title><style>@page{size:A4;margin:0}body{font:16px Arial;padding:40px;color:#20352f}dl{display:grid;grid-template-columns:1fr 2fr;gap:16px}dt{font-weight:bold}dd{margin:0}button{display:none}.receipt-amount{font-size:30px;font-weight:bold}.receipt-state{font-weight:bold;color:#914033}</style></head><body>'+document.querySelector('.receipt').outerHTML+'</body></html>');popup.document.close();popup.focus();popup.print();};
 return <article className="receipt"><p className="overline">APES · REÇU DE REMBOURSEMENT</p><h2>{reference}</h2>{row.reversed_at&&<p className="receipt-state">VERSEMENT ANNULÉ · {row.reversal_reason}</p>}<p className="receipt-amount">{money(row.amount)}</p><dl><dt>Salarié</dt><dd>{row.Nom} {row.Prenom}</dd><dt>Matricule</dt><dd>{row.matricule_sal}</dd><dt>Prêt</dt><dd>{row.loan_code}</dd><dt>Échéance</dt><dd>N° {row.num_versement} · {date(row.date_echeance)}</dd><dt>Enregistré le</dt><dd>{new Date(row.recorded_at).toLocaleString('fr-FR')}</dd><dt>Enregistré par</dt><dd>{row.recorded_username}</dd></dl><p className="table-note">Ce reçu atteste de l’enregistrement dans APES. Il ne remplace pas une preuve bancaire.</p><button className="primary" onClick={print}>Imprimer / PDF</button></article>;
}
function Field({field:[key,label,type],value,onChange,regions,roles,directory,disabled,optional,allowedMonths}){
 if(key==='avaliste')return <MemberSearch label={label} value={value} onChange={onChange} directory={directory} disabled={disabled}/>;
 const options=type==='employees'?directory.map(e=>[e.Matricule,e.Matricule+' · '+e.Nom+' '+e.Prenom]):type==='regions'?regions.map(r=>[r.idregion,r.intitule]):type==='roles'?roles.map(r=>[r.RID,r.name]):type==='months'?months.map((m,i)=>[i+1,m]).filter(([n])=>!allowedMonths||allowedMonths.includes(n)):type==='period'?[['1','Mensuel'],['3','Trimestriel'],['6','Semestriel'],['12','Annuel']]:type==='status'?[[1,'Actif'],[0,'Désactivé']]:type==='chargeType'?[["Entrée","Entrée"],["Sortie","Sortie"],...(value&&!['Entrée','Sortie'].includes(value)?[[value,value]]:[])]:type==='closureType'?[['contributions','Cotisations'],['loans','Prêts']]:null;
 return <label className={type==='checkbox'?'checkbox-label':''}>{label}{options?<select value={value??''} required disabled={disabled} onChange={e=>onChange(['period','closureType','employees','chargeType'].includes(type)?e.target.value:Number(e.target.value))}><option value="" disabled>Choisir…</option>{options.map(([v,t])=><option key={v} value={v}>{t}</option>)}</select>:type==='checkbox'?<input type="checkbox" checked={!!value} onChange={e=>onChange(e.target.checked)}/>:<input type={type||'text'} required={!optional} disabled={disabled} value={value??''} step={type==='number'?'0.01':undefined} min={type==='number'?(key==='MontantCot'?3000:0):undefined} minLength={type==='password'&&key!=='current'?6:undefined} onChange={e=>onChange(type==='number'?e.target.value===''?'':Number(e.target.value):e.target.value)}/>}</label>;
}
function Table({rows,columns,id,actions,title}){
 const [page,setPage]=useState(0),[size,setSize]=useState(10);
 useEffect(()=>{setPage(0);},[rows,id]);
 const pages=Math.max(1,Math.ceil(rows.length/size)),current=Math.min(page,pages-1),start=current*size;
 const renderTable=(items,withActions)=> <table><thead><tr>{columns.map(([k,t])=><th key={k}>{t}</th>)}{withActions&&<th>Actions</th>}</tr></thead><tbody>{items.map(r=><tr key={r[id]}>{columns.map(([k,,format])=><td key={k}>{['statut','status'].includes(k)?<span className={'badge '+([0,2].includes(r[k])?'neutral':'')}>{format?format(r[k],r):r[k]}</span>:format?format(r[k],r):String(r[k]??'')}</td>)}{withActions&&<td><div className="row-actions">{actions(r)}</div></td>}</tr>)}</tbody></table>;
 return <div className="paginated-table"><div className="pagination table-pagination">{title&&<h2 className="table-title">{title}</h2>}<label>Lignes par page<select aria-label="Lignes par page" value={size} onChange={e=>{setSize(Number(e.target.value));setPage(0);}}>{[10,25,50,100].map(n=><option key={n} value={n}>{n}</option>)}</select></label></div><div className="table-scroll table-screen">{renderTable(rows.slice(start,start+size),!!actions)}{!rows.length&&<div className="empty"><h3>Aucun enregistrement</h3><p>Les données apparaîtront ici après leur ajout.</p></div>}</div><div className="table-print">{renderTable(rows,false)}</div><div className="pagination table-pagination"><span className="pagination-range" role="status">{rows.length?start+1:0}–{Math.min(start+size,rows.length)} sur {rows.length}</span><div className="pagination-navigation"><IconButton icon="left" label="Page précédente" disabled={current===0} onClick={()=>setPage(current-1)}/><span>Page {current+1} / {pages}</span><IconButton icon="right" label="Page suivante" disabled={current+1>=pages} onClick={()=>setPage(current+1)}/></div></div></div>;
}

createRoot(document.getElementById('root')).render(<App/>);

function MemberStatement({data}){
 const [year,setYear]=useState(data.contributions[0]?.annee||data.year),selected=data.contributions.filter(c=>c.annee===Number(year));
 const print=()=>{const popup=window.open('','_blank','width=1000,height=800');if(!popup)return;popup.document.write('<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Dossier membre APES</title><style>@page{size:A4;margin:0}body{font:12px Arial;color:#20352f;padding:24px}h2,h3{margin-top:24px}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border-bottom:1px solid #ddd;padding:8px;text-align:left}button,select,.count,.statement-controls{display:none}.stats{display:flex;gap:24px}.stat strong,.stat span{display:block}img{width:48px;height:48px}.table-scroll{overflow:visible}</style></head><body>'+document.querySelector('.member-statement').outerHTML+'</body></html>');popup.document.close();popup.focus();popup.print();};
 return <article className="member-statement"><div className="section-heading"><div><div className="brand"><img className="brand-logo" src="/apes-logo.svg" alt=""/>APES</div><h3>{data.employee.Nom} {data.employee.Prenom}</h3><p className="muted">Matricule {data.employee.Matricule} · {data.employee.Region||'Région non renseignée'} · {data.employee.SITE||'Site non renseigné'}</p></div><button onClick={print}>Imprimer / PDF</button></div><p className="table-note">Situation au {date(data.asOf)} · Cotisation mensuelle prévue : {money(data.employee.MontantCot)}</p><div className="stats"><article className="stat"><span>Solde des cotisations · {data.year}</span><strong>{money(data.summary.contributionBalance)}</strong></article><article className="stat"><span>Échéances restantes · prêts ouverts</span><strong>{money(data.summary.outstanding)}</strong></article><article className="stat"><span>En retard · {data.summary.overdueCount} échéance(s)</span><strong>{money(data.summary.overdue)}</strong></article></div><h3>Cotisations par année</h3><p className="table-note">Les reports sont inclus dans chaque solde annuel. Ne pas additionner les soldes de plusieurs années.</p><Table rows={data.contributions} id="id" columns={[['annee','Année'],['report','Report',money],['paid','Versements déclarés',money],['closedTotal','Cotisations calculées · mois clôturés',money],['DroitAdhesion','Adhésion',money],['Dimunition','Réduction',money],['SoldeAnnuel','Solde',money],['statut','État',v=>v===1?'Actif':'Arrêté']]}/><h3>Versements mensuels · {year}</h3>{data.contributions.length>0&&<label className="statement-controls">Année<select value={year} onChange={e=>setYear(Number(e.target.value))}>{[...new Set(data.contributions.map(c=>c.annee))].map(y=><option key={y} value={y}>{y}</option>)}</select></label>}<Table rows={months.map((month,i)=>({id:i,month,amount:selected.reduce((s,c)=>s+Number(c[month]||0),0),calculated:selected.reduce((s,c)=>s+(i<Number(c.closedMonth)?Number(c.montant||0):0),0)}))} id="id" columns={[['month','Mois'],['amount','Versements déclarés',money],['calculated','Cotisations calculées · mois clôturés',money]]}/><h3>Prêts</h3><Table rows={data.loans} id="IDP" columns={[['code','Référence'],['montant','Montant',money],['montant_apport','Apport',money],['taux','Taux (%)'],['statut','Étape',v=>statuses[v]||'À vérifier']]}/><h3>Échéancier complet</h3><Table rows={data.payments} id="IDECH" columns={[['code_pret','Prêt'],['num_versement','N°'],['date_echeance','Échéance',date],['montant_remb','Prévu',money],['total_amorti','Déjà versé',money],['remaining','Reste à verser',money]]}/><p className="table-note">Ce dossier présente les enregistrements APES et les soldes actuels. Il ne constitue pas un relevé bancaire. Les dates des anciens versements ne sont pas reconstituées.</p></article>;
}

function Dashboard({data,user,changePage,refresh}){
 const month=data.trend[Number(data.asOf.slice(5,7))-1];
 return <><section className="dashboard-intro"><div><span className="pill">{user.isAdmin?'PILOTAGE DE L’ASSOCIATION':'MON ESPACE MEMBRE'}</span><h2>Bonjour {user.first_name||user.username}.</h2><p className="muted">Votre situation au {date(data.asOf)}. Retrouvez les opérations à suivre et les chiffres de {data.year}.</p></div><IconButton icon="refresh" label="Actualiser" onClick={refresh}/></section><div className="stats">{[['Cotisations calculées',money(data.closedContributions),'de janvier au dernier mois clôturé','contributions'],['Salariés',data.members,'membres enregistrés','employees'],['Solde des cotisations',money(data.contributions),'année '+data.year+', reports et déductions inclus','contributions'],['Prêts en cours',data.loans,'demandes et prêts ouverts','loans'],['Échéances restantes',money(data.outstanding),'solde des prêts ouverts','loans']].map(([label,value,note,page])=><button className="stat dashboard-stat" key={label} disabled={!userCan(user,page)} onClick={()=>changePage(page)}><span>{label} ↗</span><strong>{value}</strong><small>{note}</small></button>)}</div><div className="dashboard-grid"><section className="card dashboard-followup"><p className="overline">À SUIVRE</p><h2>Les priorités du jour</h2><button className="priority-row" disabled={!userCan(user,'arrears')} onClick={()=>changePage('arrears')}><span><b>Échéances en retard</b><small>{data.overdueCount} échéance(s) · {money(data.overdue)}</small></span><span className={data.overdueCount?'priority-count warning':'priority-count'}>{data.overdueCount}</span></button><button className="priority-row" disabled={!userCan(user,'loans')} onClick={()=>changePage('loans')}><span><b>Demandes en validation</b><small>{user.isAdmin?'Consulter les étapes et les signatures':'Suivre l’avancement de mes demandes'}</small></span><span className="priority-count">{data.pending}</span></button><p className="table-note">Une échéance due aujourd’hui n’est pas encore en retard. Aucune pénalité automatique.</p></section><section className="card"><p className="overline">{months[Number(data.asOf.slice(5,7))-1]} · {data.year}</p><h2>Ce mois-ci</h2><div className="month-metric"><span>Cotisations déclarées</span><strong>{money(month.contributions)}</strong></div><div className="month-metric"><span>Remboursements datés nets</span><strong>{money(month.received)}</strong></div><div className="month-metric"><span>Échéances prévues</span><strong>{money(month.scheduled)}</strong></div>{user.isAdmin&&<div className="month-metric"><span>Sorties enregistrées</span><strong>{money(month.charges)}</strong></div>}</section></div><section className="card dashboard-chart"><div className="section-heading"><div><p className="overline">ÉVOLUTION · {data.year}</p><h2>Une année en chiffres</h2></div>{user.isAdmin&&<button disabled={!userCan(user,'reports')} onClick={()=>changePage('reports')}>Ouvrir le bilan →</button>}</div><MonthlyChart rows={data.trend}/><details><summary>Voir les montants mensuels</summary><Table rows={data.trend} id="month_number" columns={[['month','Mois'],['contributions','Cotisations déclarées',money],['closedContributions','Cotisations calculées · mois clôturés',money],['scheduled','Échéances prévues',money],['received','Remboursements datés',money],...(user.isAdmin?[['charges','Charges',money]]:[])]}/></details><p className="table-note">Cotisations affectées aux mois déclarés, remboursements datés hors annulations. Les anciens versements sans date ne sont pas répartis. Ces indicateurs ne constituent pas un solde bancaire.</p></section><div className="dashboard-grid"><section className="card"><div className="section-heading"><h2>Prochaines échéances</h2><button disabled={!userCan(user,'loans')} onClick={()=>changePage('loans')}>Voir les prêts</button></div><Table rows={data.upcoming} id="IDECH" columns={[['code','Prêt'],['matricule_sal','Matricule'],['date_echeance','Date',date],['remaining','Reste',money]]}/></section><section className="card"><div className="section-heading"><h2>Derniers remboursements</h2><button disabled={!userCan(user,'repayments')} onClick={()=>changePage('repayments')}>Voir le journal</button></div><Table rows={data.recent} id="id" columns={[['loan_code','Prêt'],['amount','Montant',money],['recorded_at','Date',date],['reversed_at','État',v=>v?'Annulé':'Enregistré']]}/></section></div>{user.isAdmin&&<div className="dashboard-grid"><section className="card"><h2>Répartition des membres</h2>{data.regions.length?data.regions.map(r=><div className="region-metric" key={r.region}><div><span>{r.region}</span><strong>{r.members}</strong></div><progress value={r.members} max={Math.max(1,data.members)} aria-label={r.region+' : '+r.members+' membres'}/></div>):<p className="muted">Aucun membre enregistré.</p>}<p className="table-note">Les six régions les plus représentées.</p></section><section className="card"><h2>Charges et placements</h2><div className="month-metric"><span>Sorties · toutes années</span><strong>{money(data.charges)}</strong></div><div className="month-metric"><span>Fonds placés</span><strong>{money(data.placements)}</strong></div><button className="quick-link" disabled={!userCan(user,'charges')} onClick={()=>changePage('charges')}>Consulter les charges →</button><button className="quick-link" disabled={!userCan(user,'placements')} onClick={()=>changePage('placements')}>Consulter les placements →</button></section></div>}</>;
}

function ProfileMenu({user,onAccount,onLogout}){
 const [open,setOpen]=useState(false),container=useRef(null),trigger=useRef(null);
 useEffect(()=>{if(!open)return;const outside=e=>{if(!container.current?.contains(e.target))setOpen(false);};const escape=e=>{if(e.key==='Escape'){setOpen(false);trigger.current?.focus();}};document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);};},[open]);
 return <div className="profile" ref={container} onBlur={e=>{if(!e.currentTarget.contains(e.relatedTarget))setOpen(false);}}><button ref={trigger} className="profile-trigger" aria-expanded={open} aria-controls="profile-options" onClick={()=>setOpen(v=>!v)}><span className="avatar">{user.first_name?.[0]||user.username[0]}</span><span className="profile-identity"><strong>{user.first_name||user.username}</strong><small>{user.roles.join(', ')}</small></span><span className="profile-chevron" aria-hidden="true">{open?'▴':'▾'}</span></button>{open&&<div className="profile-options" id="profile-options"><button onClick={()=>{setOpen(false);onAccount();}}>Changer de mot de passe</button><button className="profile-logout" onClick={()=>{setOpen(false);onLogout();}}>Déconnexion</button></div>}</div>;
}

function Login({onLogin,busy,error}){
 const [showPassword,setShowPassword]=useState(false);
 return <main className="login-layout"><section className="login-story"><div className="brand"><img className="brand-logo" src="/apes-logo.svg" alt="" width="56" height="56"/><div>APES<small>GESTION ASSOCIATIVE</small></div></div><div className="login-message"><p className="overline">LA SOLIDARITÉ NOUS RASSEMBLE</p><h1>Ensemble,<br/>faisons grandir<br/><em>nos projets.</em></h1><p>Un espace commun pour vos cotisations, vos prêts et la vie de votre association.</p></div><div className="login-emblem" aria-hidden="true"><span className="emblem-orbit orbit-one"/><span className="emblem-orbit orbit-two"/><img src="/apes-logo.svg" alt=""/><span className="emblem-dot dot-one"/><span className="emblem-dot dot-two"/><span className="emblem-dot dot-three"/></div><div className="login-benefits"><div><span aria-hidden="true">◎</span><strong>Membres</strong><small>Un collectif qui avance</small></div><div><span aria-hidden="true">▤</span><strong>Cotisations</strong><small>Des versements suivis</small></div><div><span aria-hidden="true">↗</span><strong>Prêts</strong><small>Des projets accompagnés</small></div></div><p className="login-signature">Confiance <span>·</span> Solidarité <span>·</span> Transparence</p></section><section className="login-panel"><div className="login-form-wrap"><div className="login-form-heading"><span className="pill">VOTRE ESPACE APES</span><h2>Heureux de vous retrouver.</h2><p className="muted">Connectez-vous pour suivre votre situation et retrouver votre association.</p></div><form onSubmit={onLogin}>{error&&<div role="alert" className="alert error">{error}</div>}<label>Identifiant ou matricule<span className="login-input"><span className="input-symbol" aria-hidden="true">@</span><input name="username" placeholder="Votre identifiant ou matricule" required autoComplete="username" autoFocus/></span></label><label>Mot de passe<span className="login-input"><svg className="input-lock" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3" stroke="currentColor" strokeWidth="1.7"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round"/></svg><input name="password" type={showPassword?'text':'password'} placeholder="Votre mot de passe" required autoComplete="current-password"/><button className="password-toggle" type="button" title={showPassword?'Masquer le mot de passe':'Afficher le mot de passe'} aria-label={showPassword?'Masquer le mot de passe':'Afficher le mot de passe'} aria-pressed={showPassword} onClick={()=>setShowPassword(v=>!v)}><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z" stroke="currentColor" strokeWidth="1.7" strokeLinejoin="round"/><circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="1.7"/>{showPassword&&<path d="m3 3 18 18" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>}</svg></button></span></label><button className="primary full login-submit" disabled={busy}>{busy?'Connexion…':'Se connecter'}<span aria-hidden="true">→</span></button><p className="login-help">Besoin d’un accès ou d’aide ?<br/><strong>Contactez votre administrateur.</strong></p></form><div className="login-form-footer"><span className="status-dot"/> Votre association, à portée de main.</div></div></section></main>;
}

